-- PORTAL AGENTS — cài "Agent" kiểu AI Portal (assistant có base_url expose /metadata + /ask).
-- Khác portal_apps (frontend/tool): agent là dịch vụ LLM ngoài, Tizia chat-proxy tới base_url.
CREATE TABLE IF NOT EXISTS portal_agents (
  id            bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  owner_id      bigint NOT NULL,
  alias         text   NOT NULL,
  name          text   NOT NULL,
  icon          text,
  base_url      text   NOT NULL,
  description   text,
  config_json   text,
  is_public     bigint NOT NULL DEFAULT 0,
  is_active     bigint NOT NULL DEFAULT 1,
  installed_at  bigint NOT NULL,
  updated_at    bigint NOT NULL,
  UNIQUE(owner_id, alias)
);
CREATE INDEX IF NOT EXISTS idx_portal_agents_owner ON portal_agents(owner_id);
CREATE INDEX IF NOT EXISTS idx_portal_agents_public ON portal_agents(is_public) WHERE is_public = 1;
