-- =====================================================================
-- PHARMACOMM — Lưu phiên thực hành nhà thuốc 3D (yêu cầu #142, 19/08,
-- ThS Nguyệt Phương). Trước đây hội thoại + thao tác 3D CHỈ nằm trong bộ nhớ
-- máy chủ (server/pharmacy.js) nên mất sạch mỗi lần khởi động lại; 4 bảng dưới
-- đây lưu bền vững để chấm điểm và xem lại. ĐỘC LẬP với gpp_* (đề tài khác).
-- Định danh SV tự khai (mã SV + họ tên + lớp), KHÔNG mật khẩu — đúng đặc tả.
-- =====================================================================
CREATE TABLE IF NOT EXISTS pharmacy_practice_session (
  session_id        text PRIMARY KEY,            -- UUID do server sinh
  student_code      text NOT NULL,
  student_name      text NOT NULL,
  class_name        text NOT NULL,
  scenario_code     text NOT NULL,               -- vd OTC-02
  scenario_name     text,
  scenario_version  text,
  rubric_version    text,
  ai_model_version  text,
  started_at        bigint NOT NULL,
  completed_at      bigint,
  duration_ms       bigint,
  status            text NOT NULL DEFAULT 'in_progress',  -- in_progress|completed|scoring_failed
  total_score       double precision,            -- điểm chung, tiện truy vấn nhanh
  chat_session_id   text,                        -- id phiên chat in-memory để đối soát
  user_ref          text,                        -- player_name Tizia nếu có đăng nhập
  created_at        bigint NOT NULL,
  updated_at        bigint NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_pps_student ON pharmacy_practice_session(student_code, started_at DESC);
CREATE INDEX IF NOT EXISTS idx_pps_scenario ON pharmacy_practice_session(scenario_code, started_at DESC);

-- Hội thoại: lưu NGAY sau mỗi lượt trao đổi (không đợi kết thúc tình huống).
CREATE TABLE IF NOT EXISTS pharmacy_practice_message (
  message_id     bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  session_id     text NOT NULL,
  speaker        text NOT NULL,                  -- 'student' | 'patient'
  content        text NOT NULL,
  message_order  integer NOT NULL,
  created_at     bigint NOT NULL,
  UNIQUE (session_id, message_order)             -- chặn gửi trùng một lời thoại
);
CREATE INDEX IF NOT EXISTS idx_ppmsg_session ON pharmacy_practice_message(session_id, message_order);

-- Nhật ký thao tác chuyên môn trong môi trường 3D (chỉ sự kiện CÓ Ý NGHĨA
-- đánh giá — không lưu chuyển động chuột/camera/khung hình).
CREATE TABLE IF NOT EXISTS pharmacy_practice_action (
  action_id       bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  session_id      text NOT NULL,
  action_type     text NOT NULL,                 -- pick_box | inspect_drug | label_dose | ...
  object_id       text,
  object_name     text,
  quantity        integer,
  action_result   text NOT NULL DEFAULT 'success',-- success|invalid|cancelled|corrected
  action_details  text,                          -- JSON: hàm lượng, dạng bào chế, hạn dùng…
  description_vi  text,                          -- mô tả tiếng Việt hiển thị ở trang kết quả
  action_order    integer NOT NULL,
  created_at      bigint NOT NULL,
  UNIQUE (session_id, action_order)              -- chặn gửi trùng một thao tác
);
CREATE INDEX IF NOT EXISTS idx_ppact_session ON pharmacy_practice_action(session_id, action_order);

-- Kết quả chấm: mỗi tiêu chí A1..E5 một dòng (chấm lại thì UPSERT, không nhân bản).
CREATE TABLE IF NOT EXISTS pharmacy_practice_score (
  score_id             bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  session_id           text NOT NULL,
  criterion_code       text NOT NULL,            -- A1..E5
  criterion_name       text NOT NULL,
  criterion_group      text NOT NULL,            -- A..E
  score                double precision NOT NULL,
  max_score            double precision NOT NULL DEFAULT 4,
  evidence_source      text NOT NULL,            -- conversation|action_3d|combined
  evidence             text,
  comment              text,
  improvement_feedback text,
  scored_at            bigint NOT NULL,
  UNIQUE (session_id, criterion_code)
);
CREATE INDEX IF NOT EXISTS idx_ppscore_session ON pharmacy_practice_score(session_id, criterion_code);

-- =====================================================================
-- PHARMACOMM — Mô hình truy cập Sinh viên / Giảng viên (req #143, 22/08)
-- =====================================================================

-- Hồ sơ sinh viên: MÃ SV là định danh duy nhất. Thực hành nhiều lượt vẫn chỉ
-- một hồ sơ (đặc tả: "không tạo hồ sơ trùng"). Họ tên/lớp cập nhật theo lần
-- khai gần nhất để sửa được lỗi gõ, nhưng lịch sử vẫn gắn theo mã SV.
CREATE TABLE IF NOT EXISTS pharmacy_student (
  student_code  TEXT PRIMARY KEY,
  student_name  TEXT NOT NULL,
  class_name    TEXT NOT NULL,
  first_seen_at BIGINT NOT NULL,
  last_seen_at  BIGINT NOT NULL,
  session_count BIGINT NOT NULL DEFAULT 0
);
CREATE INDEX IF NOT EXISTS idx_pstudent_class ON pharmacy_student(class_name, student_code);

-- Tài khoản giảng viên: TẠO SẴN khi triển khai, KHÔNG có route đăng ký công khai.
-- Mật khẩu băm bằng scrypt (Node crypto, memory-hard cùng hạng argon2/bcrypt).
CREATE TABLE IF NOT EXISTS pharmacy_teacher (
  username       TEXT PRIMARY KEY,
  password_hash  TEXT NOT NULL,
  display_name   TEXT NOT NULL,
  role           TEXT NOT NULL DEFAULT 'TEACHER',
  must_change_pw BOOLEAN NOT NULL DEFAULT TRUE,
  created_at     BIGINT NOT NULL,
  updated_at     BIGINT NOT NULL
);

-- Phiên đăng nhập giảng viên (token mờ trong cookie httpOnly riêng).
CREATE TABLE IF NOT EXISTS pharmacy_teacher_session (
  token      TEXT PRIMARY KEY,
  username   TEXT NOT NULL REFERENCES pharmacy_teacher(username) ON DELETE CASCADE,
  created_at BIGINT NOT NULL,
  expires_at BIGINT NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_pteacher_sess_user ON pharmacy_teacher_session(username, expires_at DESC);

-- Nhật ký: đăng nhập, xem dữ liệu, xuất dữ liệu (đặc tả mục 3).
CREATE TABLE IF NOT EXISTS pharmacy_teacher_log (
  id         BIGSERIAL PRIMARY KEY,
  username   TEXT,
  action     TEXT NOT NULL,
  detail     TEXT,
  ip         TEXT,
  created_at BIGINT NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_pteacher_log_time ON pharmacy_teacher_log(created_at DESC);

-- Phân loại lượt thực hành: STUDENT | GUEST | TEACHER_TEST.
-- Lượt chạy thử của giảng viên KHÔNG được tính vào lịch sử/thống kê sinh viên.
ALTER TABLE pharmacy_practice_session
  ADD COLUMN IF NOT EXISTS session_kind TEXT NOT NULL DEFAULT 'STUDENT';
CREATE INDEX IF NOT EXISTS idx_pps_kind ON pharmacy_practice_session(session_kind, started_at DESC);

-- =====================================================================
-- GPP 2D — Thực hành nghiệp vụ nhà thuốc GPP (đề tài ThS Phạm Thị Hương Lý,
-- Trường CĐ Y tế HN). Module ĐỘC LẬP với Nhà thuốc 3D: bảng riêng prefix gpp_,
-- không FK tới users (định danh SV bằng mã SV + lớp để phục vụ nghiên cứu, chạy
-- được cả khi dùng tài khoản chung). Xoá hẳn module = drop 5 bảng này, không
-- ảnh hưởng phần còn lại.
-- =====================================================================
CREATE TABLE IF NOT EXISTS gpp_participant (
  id            bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  student_code  text   NOT NULL,          -- mã SV (định danh nghiên cứu)
  full_name     text,
  class_name    text,
  year_level    smallint,                 -- 2 = năm 2 (Dược lý) | 3 = năm 3 (KNTH)
  study_group   text,                     -- 'exp' nhóm thực nghiệm | 'ctrl' nhóm đối chứng
  user_ref      text,                     -- player_name từ session Tizia nếu có (chỉ để đối soát)
  created_at    bigint NOT NULL,
  updated_at    bigint NOT NULL,
  UNIQUE(student_code)
);
CREATE TABLE IF NOT EXISTS gpp_session (
  id            text   PRIMARY KEY,        -- s_xxx
  participant_id bigint,
  started_at    bigint NOT NULL,
  ended_at      bigint,
  meta          text                       -- JSON tuỳ ý (thiết bị, phiên bản đề…)
);
-- Nhật ký hệ thống: mỗi thao tác/quyết định của SV trong 1 cấp (phục vụ đo hiệu suất).
CREATE TABLE IF NOT EXISTS gpp_event (
  id            bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  session_id    text,
  participant_id bigint,
  level         smallint,                  -- 1..4 (0 = trò chơi kiến thức)
  step_key      text,                      -- mã bước bảng kiểm
  action        text,                      -- loại thao tác
  correct       smallint,                  -- 1 đạt | 0 không đạt
  attempts      smallint,                  -- số lần thử ở bước này
  time_ms       bigint,                    -- thời gian tính từ khi vào bước
  detail        text,                      -- JSON tuỳ ý
  created_at    bigint NOT NULL
);
-- Kết quả 1 cấp hoặc lượt trò chơi: điểm tổng, số bước đạt, thời gian.
CREATE TABLE IF NOT EXISTS gpp_level_result (
  id            bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  session_id    text,
  participant_id bigint,
  level         smallint NOT NULL,
  passed        smallint,                  -- 1 qua ngưỡng mở khoá | 0
  score         double precision,          -- % đạt
  steps_total   smallint,
  steps_passed  smallint,
  duration_ms   bigint,
  attempts_total smallint,
  detail        text,                      -- JSON: từng bước đạt/không
  created_at    bigint NOT NULL
);
-- Bài trắc nghiệm đo trước/sau (pre/post) — kiến thức.
CREATE TABLE IF NOT EXISTS gpp_test_result (
  id            bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  participant_id bigint,
  session_id    text,
  phase         text NOT NULL,             -- 'pre' | 'post'
  form_variant  text,                      -- 'A' | 'B' (đề song song)
  year_level    smallint,
  n_questions   smallint,
  n_correct     smallint,
  score10       double precision,          -- quy về thang 10
  answers       text,                      -- JSON: [{qid,pick,correct}]
  created_at    bigint NOT NULL
);
-- Thang đo cuối buổi: ARCS (động lực), tải nhận thức, SUS (khả dụng).
CREATE TABLE IF NOT EXISTS gpp_survey (
  id            bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  participant_id bigint,
  session_id    text,
  kind          text NOT NULL,             -- 'arcs' | 'clt' | 'sus'
  items         text,                      -- JSON: [{id,val}]
  summary       text,                      -- JSON: điểm tổng/nhóm (vd SUS 0-100)
  created_at    bigint NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_gpp_event_participant ON gpp_event(participant_id);
CREATE INDEX IF NOT EXISTS idx_gpp_levelresult_participant ON gpp_level_result(participant_id);
CREATE INDEX IF NOT EXISTS idx_gpp_testresult_participant ON gpp_test_result(participant_id);

